from pathlib import Path
from bs4 import BeautifulSoup
import shutil
R=Path(__file__).parent;D=R/'dist'
# Use the supplied artwork intact, without altering its pixels.
shutil.copyfile(R/'design/client-logo.png',D/'assets/zagara-client-logo.png')
def photo(term):return '/assets/'+next(p.name for p in (D/'assets').glob('*.webp') if term in p.name)
grapes=photo('slide-uva-b');orange=photo('sicilia');tomato=photo('slide-pom');lemons=photo('slide-limoni')
def scene(num,title,desc,img,id):
 return f'<section class="cinema-scene" id="{id}"><img class="cinema-photo" src="{img}" alt="I frutti La Zagara" loading="lazy"><div class="cinema-overlay"></div><div class="scene-copy"><span class="eyebrow">CAPITOLO {num} · LA ZAGARA</span><h2>{title}</h2><p>{desc}</p><a class="button light" href="/prodotti">Esplora i nostri frutti ↗</a></div><span class="scene-number" aria-hidden="true">{num}</span></section>'
territory='''<section class="territory-story wrap"><div class="territory-label"><span class="eyebrow">01 / IL TERRITORIO</span><h2>Tra il vulcano<br>e il mare.<br><em>La nostra origine.</em></h2></div><div class="territory-text"><p class="lead">Fiumefreddo di Sicilia. Un nome che custodisce il legame di La Zagara con la propria terra.</p><p>I nostri agrumeti si trovano alle pendici dell’Etna. Da qui parte un racconto agricolo fatto di agrumi, uva da tavola e ortofrutta, di coltivazione in serra e in campo aperto, di esperienza e ricerca.</p><p>La produzione di uva intreccia Sicilia e Puglia: territori diversi, uniti dall’attenzione alle varietà e al prodotto. La commercializzazione porta questo lavoro anche verso la grande distribuzione europea.</p><div class="territory-tags"><span>SICILIA</span><span>PUGLIA</span><span>EUROPA</span></div><a class="text-link" href="/chi-siamo">Le persone e la nostra filosofia ↗</a></div></section>'''
varieties='''<section class="fruit-atlas wrap"><div class="section-heading"><div><span class="eyebrow">02 / UN ATLANTE DI SAPORI</span><h2>Il dettaglio<br>fa la <em>differenza.</em></h2></div><p>Ogni famiglia di frutti apre un mondo di forme,<br>consistenze e varietà da conoscere.</p></div><div class="atlas-rows">'''
for i,(name,desc,tags,url,img) in enumerate([
 ('Uva da tavola','Dalle varietà tradizionali alle selezioni senza semi, una gamma che attraversa colori e caratteristiche differenti.','Vittoria · Italia · Red Globe · SNFL · IFG','uva-da-tavola',grapes),
 ('Arance','La Sicilia si racconta anche attraverso le sue arance: polpa rossa e bionda, selezioni e tempi di maturazione diversi.','Moro · Tarocco · Sanguinello · Lane Late · Tacle','arance',orange),
 ('Limoni','Il profumo degli agrumi incontra la ricchezza delle fioriture: Primofiore, Bianchetto e Verdello scandiscono il Femminello Siracusano.','Femminello Siracusano · Zagara Bianca','limoni',lemons),
 ('Pomodori','Piccoli frutti dal carattere riconoscibile: il Ciliegino, la dolcezza del Datterino e la consistenza del Piccadilly.','Ciliegino · Datterino · Piccadilly','pomodori',tomato)]):
 varieties+=f'<a class="atlas-row" href="/prodotti/{url}"><span class="atlas-index">0{i+1}</span><img src="{img}" loading="lazy" alt="{name}"><div><h3>{name}</h3><p>{desc}</p><span class="atlas-tags">{tags}</span></div><span class="atlas-arrow">↗</span></a>'
varieties+='</div></section>'
care='''<section class="care-chapter"><div class="wrap"><span class="eyebrow">03 / IL VALORE DELLA CURA</span><h2>La qualità non è<br>un singolo gesto.<br><em>È un modo di lavorare.</em></h2><div class="care-grid"><article><span>LA COLTIVAZIONE</span><h3>Rispettare l’origine.</h3><p>Metodi tradizionali e naturali, attenzione alla genuinità e una produzione che comprende serra e campo aperto. La terra è parte del valore del prodotto.</p></article><article><span>L’INNOVAZIONE</span><h3>Cercare nuove possibilità.</h3><p>Varietà esclusive di uva senza semi e arance Tarocco affiancano la gamma tradizionale. L’innovazione comprende anche macchinari all’avanguardia.</p></article><article><span>IL CONSUMATORE</span><h3>Seguire ogni passaggio.</h3><p>Controlli, elevati standard qualitativi e tutela del consumatore accompagnano l’attività. L’attenzione all’ambiente comprende i packaging EcoFriendly.</p></article></div></div></section>'''
season='''<section class="season-chapter wrap"><span class="eyebrow">04 / IL TEMPO DELLA NATURA</span><h2>Non tutto nasce<br><em>nello stesso momento.</em></h2><div class="season-columns"><p>Le varietà raccontano anche il tempo: selezioni precoci, di media stagione e tardive, fioriture e raccolti. Conoscere la stagionalità significa avvicinarsi al prodotto con maggiore attenzione.</p><div><p>I calendari La Zagara aiutano a orientarsi nella gamma. Per la disponibilità attuale e per una fornitura, il riferimento è sempre il contatto diretto con l’azienda.</p><a class="text-link" href="/assets/Calendario_prodotti.pdf">Calendario prodotti PDF ↗</a><br><a class="text-link" href="/assets/Calendario_uva.pdf">Calendario uva PDF ↗</a></div></div></section>'''
for f in D.rglob('index.html'):
 s=BeautifulSoup(f.read_text(encoding='utf8'),'html.parser');m=s.select_one('main')
 for im in s.select('.brand img,.footer-about img'):im['src']='/assets/zagara-client-logo.png';im['alt']='La Zagara — Fiumefreddo di Sicilia'
 if s.select_one('.cinema-edition'):continue
 key=f.parent.name if f.parent!=D else 'home'
 wrapper=s.new_tag('div',attrs={'class':'cinema-edition'})
 if key=='home':
  wrapper.append(BeautifulSoup(territory+scene('01','Una terra da vivere.<br><em>Un gusto da ricordare.</em>','Il racconto comincia nei campi. E continua ogni volta che un frutto porta con sé il carattere della sua origine.',orange,'la-terra')+varieties+care+scene('02','La passione cresce.<br><em>Grappolo dopo grappolo.</em>','Varietà standard ed esclusive. Con e senza semi. L’uva da tavola è uno dei protagonisti del mondo La Zagara.',grapes,'la-passione')+season,'html.parser'))
  anchor=s.select_one('.ticker');anchor.insert_after(wrapper)
 elif key in ['chi-siamo','prodotti']:
  wrapper.append(BeautifulSoup(territory+varieties+care+season,'html.parser'));m.append(wrapper)
 elif s.select_one('.varieties'):
  wrapper.append(BeautifulSoup(scene('01','Da osservare.<br><em>Da conoscere.</em>','Le differenze tra le varietà sono parte del piacere di scegliere. Esplora le caratteristiche e consulta i calendari La Zagara.',s.select_one('.product-hero img')['src'],'il-dettaglio')+season,'html.parser'));m.append(wrapper)
 elif key=='gallery':
  wrapper.append(BeautifulSoup(scene('01','Ogni immagine,<br><em>una parte di noi.</em>','I prodotti, gli spazi di lavoro e i luoghi della produzione: fotografie che avvicinano al mondo dell’azienda.',tomato,'il-racconto'),'html.parser'));m.insert(1,wrapper)
 elif key in ['news','contatti']:wrapper.append(BeautifulSoup(season,'html.parser'));m.append(wrapper)
 f.write_text(str(s),encoding='utf8')
css=D/'style.css'
if '/* Cinema edition */' not in css.read_text(encoding='utf8'):
 css.write_text(css.read_text(encoding='utf8')+'''\n/* Cinema edition */
.brand{width:195px;height:90px;display:flex;align-items:center;overflow:hidden}.brand img{height:86px;width:100%;object-fit:contain;mix-blend-mode:multiply}.footer-about img{width:230px;max-height:180px;object-fit:contain}.cinema-scene{height:95svh;min-height:650px;position:relative;isolation:isolate;overflow:hidden;color:var(--cream);background:var(--deep)}.cinema-photo{position:absolute;inset:-8%;width:116%;height:116%;object-fit:cover;z-index:-2;will-change:transform}.cinema-overlay{position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,#071d15c9,#071d1530),linear-gradient(0deg,#071d1580,transparent)}.scene-copy{position:absolute;left:8%;right:8%;bottom:15%;max-width:950px}.scene-copy h2{font-size:clamp(55px,7.2vw,112px);margin:30px 0}.scene-copy em{color:#f5b87f}.scene-copy p{max-width:420px;color:#edf0df;font-size:14px;line-height:1.9;margin-bottom:30px}.scene-number{position:absolute;right:5%;top:5%;font:180px var(--serif);color:#ffffff24}.territory-story{display:grid;grid-template-columns:1fr 1fr;gap:12%;padding:140px 0}.territory-label{position:sticky;top:130px;align-self:start}.territory-label h2{font-size:clamp(50px,5vw,80px);margin-top:30px}.territory-text p{font-size:14px;line-height:2;margin-bottom:25px}.territory-text .lead{font:29px/1.4 var(--serif);color:var(--green)}.territory-tags{display:flex;gap:12px;padding:25px 0}.territory-tags span{border:1px solid var(--line);border-radius:30px;padding:7px 14px;font-size:9px;letter-spacing:1.5px}.fruit-atlas{padding:120px 0}.atlas-row{display:grid;grid-template-columns:35px 180px 1fr 50px;gap:40px;align-items:center;padding:35px 0;border-top:1px solid var(--line)}.atlas-index{font-size:10px;color:var(--muted)}.atlas-row img{height:160px;object-fit:cover;transition:transform .6s;border-radius:50%}.atlas-row:hover img{transform:scale(1.07) rotate(-4deg)}.atlas-row h3{font:47px var(--serif);letter-spacing:-1px;margin-bottom:15px}.atlas-row p{font-size:12px;max-width:650px}.atlas-tags{font-size:9px;letter-spacing:.8px;display:block;margin-top:17px;color:var(--muted)}.atlas-arrow{font-size:40px}.care-chapter{background:var(--deep);color:var(--cream);padding:120px 0}.care-chapter h2{font-size:clamp(55px,6vw,92px);margin:35px 0 70px}.care-chapter em{color:#f2af73}.care-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:50px}.care-grid article{padding-top:25px;border-top:1px solid #ffffff30}.care-grid article>span{font-size:9px;letter-spacing:2px;color:#b7c7ab}.care-grid h3{font:34px var(--serif);margin:25px 0 20px}.care-grid p{font-size:12px;line-height:2;color:#c6d0c0}.season-chapter{padding:120px 0}.season-chapter h2{margin:30px 0 45px}.season-columns{display:grid;grid-template-columns:1fr 1fr;gap:12%}.season-columns p{font-size:14px;line-height:2}.season-columns .text-link{margin-top:20px}.cinema-edition{overflow:clip}@media(max-width:700px){.brand{width:155px;height:70px}.brand img{height:68px}.territory-story{display:block;padding:70px 0}.territory-label{position:static}.territory-label h2{font-size:54px;margin-bottom:35px}.territory-text .lead{font-size:26px}.territory-text p{font-size:13px}.cinema-scene{height:85svh;min-height:600px}.scene-copy{left:6%;right:6%;bottom:10%}.scene-copy h2{font-size:54px}.scene-copy p{font-size:12px}.scene-number{font-size:100px}.fruit-atlas{padding:65px 0}.atlas-row{grid-template-columns:20px 80px 1fr;gap:15px;padding:25px 0}.atlas-row img{height:80px}.atlas-row h3{font-size:31px;margin-bottom:10px}.atlas-row p{font-size:11px}.atlas-tags{font-size:8px}.atlas-arrow{display:none}.care-chapter{padding:70px 0}.care-chapter h2{font-size:52px;margin-bottom:45px}.care-grid{grid-template-columns:1fr;gap:35px}.care-grid h3{font-size:32px}.care-grid p{font-size:13px}.season-chapter{padding:70px 0}.season-chapter h2{font-size:48px}.season-columns{grid-template-columns:1fr;gap:25px}.season-columns p{font-size:13px}}@media(prefers-reduced-motion:reduce){.cinema-photo{transform:none!important}.atlas-row:hover img{transform:none}}
''',encoding='utf8')
js=D/'app.js'
if '// Cinema scroll' not in js.read_text(encoding='utf8'):
 js.write_text(js.read_text(encoding='utf8')+'''\n// Cinema scroll: movement follows the viewport and respects reduced motion.
(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');const scenes=[...document.querySelectorAll('.cinema-scene')];let pending=false;function draw(){if(!media.matches)scenes.forEach(s=>{const r=s.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)s.querySelector('.cinema-photo').style.transform=`translateY(${(r.top+r.height/2-innerHeight/2)*-.12}px)`});pending=false}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(draw)}},{passive:true});draw()})();
''',encoding='utf8')
print('Cinema chapters and supplied logo applied')
